import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1197, own='cte_120.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)

# ---- 824 Blueprint Reading and Technical Drawing ----
H("824.d.1.A",3,"A machinist glances at the corner of a print to learn the part name, the drawing scale, the material and the revision level before cutting any stock. That corner is the:","title block",["bill of lading","dimension line","datum target"],"The title block holds identifying data.")
H("824.d.1.A",4,"A print's title block lists 'MATERIAL: 6061-T6' and 'SCALE: 1:2'. The machinist learns that the part is:","aluminum and drawn at half size",["steel and drawn double size","brass and full size","plastic and drawn at half size"],"Scale 1:2 means half size.")
H("824.d.1.B",3,"A drawing shows the front, top and right-side views of a bracket, each aligned with the others. The reason a print uses several views is to:","show all the features of the part from different directions",["make the page look busy","avoid dimensions","hide small details"],"Multi-views describe shape.")
H("824.d.1.B",4,"A hole appears as a circle in the top view and as two dashed lines in the front view. Those dashed lines mean the hole:","is hidden inside the part in that view",["is on the outside edge","is missing","is a thread callout"],"Dashed lines show hidden features.")
H("824.d.1.C",3,"A drawing lists one length as 1.250 in., another as 1 1/4 in. and a third as 31.75 mm. The three forms are:","decimal, fractional and metric dimensions",["only fractional dimensions","only angular dimensions","only radial dimensions"],"Prints can use all three.")
H("824.d.1.C",4,"A part is dimensioned 25.4 mm. In inches that equals:","1.000 in.",["0.254 in.","2.54 in.","10.0 in."],"25.4 mm = 1 in.")
H("824.d.1.D",3,"A print has a cutting-plane line and a view that looks as if the part were sliced open to show internal walls and cavities. This is a:","section view",["pictorial view","title view","reference view"],"Section views reveal inside details.")
H("824.d.1.D",4,"The diagonal hatch lines in a section view mark:","the solid material cut by the cutting plane",["empty space","dimension limits","center lines"],"Hatching indicates cut material.")
H("824.d.1.E",3,"A drawing shows a box as one picture with its width, height and depth all drawn on 30-degree axes. This projection is:","isometric",["orthographic","schematic","auxiliary"],"Isometric uses 30-degree axes.")
H("824.d.1.E",4,"Which projection shows the front face true shape with the depth drawn on a single receding angle line?","oblique",["isometric","orthographic with three views","schematic"],"Oblique keeps the front face undistorted.")
H("824.d.1.F",3,"A bracket has a slanted face that looks foreshortened in the normal views. A print adds a view looking straight at that face to show its true size and shape. That is an:","auxiliary view",["section view","schematic view","title view"],"Auxiliary views show inclined surfaces true size.")
H("824.d.1.F",4,"An auxiliary view is drawn perpendicular to:","the inclined surface it describes",["the title block","the border","the bill of materials"],"Projection lines are perpendicular to the inclined surface.")
H("824.d.1.G",3,"A print gives the distance between two holes, the radius of a corner and the angle of a chamfer. These are:","linear, radial and angular dimensions",["only ordinate dimensions","only pictorial notes","only title entries"],"Dimension types differ by feature.")
H("824.d.1.G",4,"In ordinate dimensioning, every feature is dimensioned from:","a common zero or origin",["the nearest edge only","the title block","the revision list"],"Ordinate uses a datum origin.")
H("824.d.1.H",3,"A sales engineer sketches a part in a single three-dimensional picture to show how an assembly goes together on the shop floor. This pictorial drawing helps manufacturing by:","showing the assembled appearance in one view",["replacing all dimensions","hiding assembly steps","listing prices"],"Pictorials aid understanding.")
H("824.d.1.H",4,"An exploded pictorial drawing is most useful for:","showing the order in which parts are assembled",["tolerance stack-up","machine speeds","payroll"],"Exploded views show assembly order.")
H("824.d.1.I",3,"A print uses a feature control frame with symbols for flatness, position and datums to control the form and location of features. This is:","geometric dimensioning and tolerancing",["only a title block","a pictorial","a schematic"],"GD&T controls form and location.")
H("824.d.1.I",4,"A major purpose of GD&T in manufacturing is to:","communicate the design's functional requirements precisely",["avoid inspection","reduce print size only","remove all tolerances"],"GD&T clarifies function.")
H("824.d.1.J",3,"A shaft is dimensioned 1.500 +0.002 / −0.001 in. The smallest acceptable diameter is:","1.499 in.",["1.498 in.","1.500 in.","1.502 in."],"1.500 − 0.001.")
H("824.d.1.J",4,"A hole is dimensioned 0.750 ± 0.005 in. A machinist measures 0.757 in. The hole is:","out of tolerance because it exceeds 0.755",["within tolerance","too small","exactly nominal"],"Upper limit is 0.755.")
H("824.d.1.K",3,"A print is marked scale 2:1. A feature measures 1 in. on the paper. On the actual part it is:","0.5 in.",["2 in.","1 in.","4 in."],"2:1 means the drawing is twice actual size.")
H("824.d.1.K",4,"If a drawing uses a 1:4 scale, a 12-in. part length would be drawn as:","3 in.",["48 in.","24 in.","6 in."],"12 ÷ 4 = 3.")
H("824.d.1.L",3,"One drawing shows what a hydraulic valve looks like on a machine. Another uses symbols and lines to show how the circuit is connected. The second is a:","schematic drawing",["pictorial drawing","section view","title block"],"Schematics use symbols.")
H("824.d.1.L",4,"A pictorial drawing differs from a schematic because a pictorial:","shows the actual appearance of the components",["shows only symbols","has no parts","is always an electrical circuit"],"Pictorial shows appearance.")
H("824.d.1.M",3,"On a print, a leader line points to a hole with the note 'Ø0.250 THRU, 4 PLACES'. This note is a:","call out",["revision block","title entry","bill of materials"],"Call outs describe features.")
H("824.d.1.M",4,"A call out that reads '1/4-20 UNC-2B' on a hole tells the machinist:","the thread size and class to cut",["the paint color","the shop number","the shipping date"],"Thread callouts give size and class.")
H("824.d.1.N",3,"A technician needs to trace how current flows to a motor, so she reads the drawing made of switch, relay and fuse symbols. That drawing is a(n):","electrical schematic",["fluid power schematic","piping drawing","section view"],"Electrical schematics show circuits.")
H("824.d.1.N",4,"A drawing showing a pump, cylinder and directional valve connected by lines is a:","fluid power schematic",["electrical schematic","floor plan","title block"],"Fluid power schematics show hydraulics and pneumatics.")
H("824.d.2.A",3,"To draw an arc with a 2-inch radius on a layout, the drafter sets the compass:","with the point on the center and the pencil 2 in. away",["with both ends on the line","with the pencil on the center","with a 4 in. opening"],"Compass radius equals the set distance.")
H("824.d.2.A",4,"A compass is used in technical drawing to make:","circles and arcs",["straight lines","dashed lines","arrowheads"],"Compasses draw circles and arcs.")
H("824.d.2.B",3,"To measure a shaft diameter to a thousandth of an inch, an inspector should use a:","micrometer",["wooden ruler","tape measure","carpenter's square"],"Micrometers read thousandths.")
H("824.d.2.B",4,"A 6-inch steel scale is best used on a drawing or part to:","read lengths to the nearest 1/64 or 1/32 inch",["read thousandths","measure threads","measure temperature"],"Scales are for coarser measurements.")
H("824.d.2.C",3,"A student uses software to draw a part, add dimensions and view it from several angles on the screen before it is cut. This is:","computer-aided design and drafting",["manual lettering","hand sketching only","printing a form"],"CAD supports drawing and design.")
H("824.d.2.C",4,"A drafter must change a hole size on a part drawing that was made in design software. Compared with redrawing by hand, the software lets her:","edit the feature and update every view quickly",["start over on paper","erase the whole file","avoid any revision record"],"CAD edits propagate to all views.")
H("824.d.2,D",3,"A machinist sees a small box in a feature control frame holding the symbol for a circle with a cross, next to a number and a datum letter. That symbol set tells the machinist the part's:","position tolerance for the feature",["paint color","price","shipping date"],"Position symbols control feature location.")
H("824.d.2,D",4,"On a blueprint, a symbol that looks like a stepped hole with a larger shallow diameter on top is the call out for a:","counterbore",["thread","chamfer","weld"],"Counterbore symbol.")
H("824.d.2.E",3,"A machinist sees one dimension on a print shown in parentheses. It is a reference dimension, which means it is:","for information only and not used to check the part",["a required inspection size","a driving dimension","a tolerance zone"],"Reference dimensions are informational.")
H("824.d.2.E",4,"A driving dimension on a print is one that:","controls the size or location and is toleranced",["is shown only for information","is always in parentheses","has no tolerance"],"Driving dimensions govern manufacturing.")
H("824.d.2.F",3,"On an electrical print, the symbol of a coil drawn with a circle labeled 'M' usually stands for a:","motor starter contactor",["gas valve","piping fitting","bolt"],"Contactors and coils appear in control prints.")
H("824.d.2.F",4,"A symbol of a circle with a lamp marking in a control circuit represents a:","pilot lamp",["fuse","relay coil","ground"],"Lamp symbols indicate indicator lights.")
H("824.d.2.G",3,"On a fluid power print, the symbol for a pump or power unit shows:","a circle with a triangle indicating flow direction",["a box with a plus sign","a rectangle with no marks","a zigzag line"],"Pump symbols include a flow triangle.")
H("824.d.2.G",4,"A rectangle with an arrow inside and two or three connected squares in a hydraulic diagram is a:","directional control valve",["storage tank","motor","gauge"],"Directional valves use boxes.")
H("824.d.2.H",3,"On a piping and instrumentation diagram (P&ID), a circle with a letter 'P' inside connected to a line usually represents a:","pressure gauge or indicator",["tank","valve actuator","switch"],"Instrument bubbles show measurements.")
H("824.d.2.H",4,"On a P&ID, a bow-tie shape on a pipe line represents:","a valve",["a pump","a gauge","a filter"],"Bow-tie is a gate valve symbol.")
H("824.d.2.I",3,"A print shows a symbol of a coil of wire as a zigzag or spiral to represent a:","spring",["fastener","thread","tank"],"Springs have standard symbols.")
H("824.d.2.I",4,"A drawing note reads 'M10 × 1.5'. This is a symbol for a:","metric thread",["spring","fastener head","hole depth"],"Metric thread notation.")
H("824.d.3.A",3,"A contractor reads a drawing that shows a building from above with walls, doors and room sizes. This is a:","floor plan",["elevation","section","detail"],"Floor plans show layout from above.")
H("824.d.3.A",4,"On a floor plan, a break in a wall with an arc drawn near it represents:","a door and its swing",["a window","a stair","a drain"],"Door swing arcs.")
H("824.d.3.B",3,"A drawing shows the front of a building as it would appear standing outside, with the height of the roof and windows. This is an:","elevation drawing",["floor plan","electrical schematic","title block"],"Elevations show exterior faces.")
H("824.d.3.B",4,"Elevation drawings are most useful for determining:","heights and exterior appearance",["room color","wiring sizes","pipe fittings"],"Elevations show vertical dimensions.")
H("824.d.3.C",3,"A drawing slices through a wall to show its framing, insulation and finish layers from inside to outside. This is a:","section view or detail",["floor plan","site plan","schedule"],"Sections show construction.")
H("824.d.3.C",4,"The best drawing for showing how a wall is built from layers is a:","wall section",["site plan","landscape plan","schedule"],"Wall sections show materials.")
H("824.d.3.D",3,"On a plan, a small circle with an 'S' next to a wall usually represents:","a light switch",["a smoke damper","a sink","a stair"],"Electrical symbols.")
H("824.d.3.D",4,"A rectangle on a wall labeled 'DP' on an electrical plan is the:","distribution panel",["door plan","drain pipe","display panel for lights"],"DP is a panel.")
H("824.d.3.E",3,"On a plumbing plan, a line showing where water enters the building and branches to fixtures is the:","water supply line",["drain stack","gas line","vent only"],"Supply lines carry water in.")
H("824.d.3.E",4,"A plumbing symbol for a floor drain looks like:","a circle with a grid or X inside",["a square with an arrow","a triangle","a zigzag"],"Floor drains use a grated circle.")
H("824.d.3.F",3,"On an HVAC drawing, a rectangle with an X inside on a ceiling usually represents a:","supply air diffuser",["water heater","light","door"],"Ceiling diffusers are marked with symbols.")
H("824.d.3.F",4,"The component on an HVAC plan that moves heated or cooled air through ducts is the:","air handler or furnace",["sink","distribution panel","drain"],"Air handlers move conditioned air.")
H("824.d.4.A",3,"A student sketches a slanted face of a bracket by projecting lines perpendicular to that face to show its true shape. She is sketching an:","auxiliary projected view",["isometric view","title block","section"],"Auxiliary views for inclined surfaces.")
H("824.d.4.A",4,"To show the true size of an inclined surface in a sketch, the student should draw the new view:","with projection lines perpendicular to the inclined surface",["with projection lines parallel to the surface","with random lines","with no lines"],"Perpendicular projection gives true shape.")
H("824.d.4.B",3,"A student draws front, top and right views of a small block, aligning them so features line up. She is creating a sketch using:","multi-views",["only a pictorial","only a schematic","only a symbol"],"Multi-view sketching.")
H("824.d.4.B",4,"In a three-view sketch, the top view is placed:","directly above the front view",["to the left of the front view","below the right view","anywhere"],"Standard layout.")
H("824.d.4.C",3,"A student adds size dimensions, extension lines, dimension lines and arrowheads to each view of a multi-view sketch. She is:","annotating the views with proper dimensioning standards",["coloring the views","erasing views","hiding the views"],"Dimensions are annotated by standard.")
H("824.d.4.C",4,"A standard practice for dimensions on a drawing is to:","avoid repeating the same dimension in multiple views",["repeat every size three times","omit all sizes","place all sizes inside the part"],"Don't duplicate dimensions.")
H("824.d.5.A",3,"A hole is dimensioned 0.500 ± 0.003 in. This is a bilateral tolerance because the allowed variation:","goes both above and below the nominal size",["goes only above","goes only below","is zero"],"Bilateral tolerances vary both ways.")
H("824.d.5.A",4,"A shaft is dimensioned 1.000 +0.000 / −0.004 in. This tolerance is:","unilateral because the variation goes only one direction",["bilateral","unknown","zero"],"Unilateral goes one way.")
H("824.d.5.B",3,"A shaft's largest allowed size is 0.998 in. and a hole's smallest allowed size is 1.000 in. The tightest clearance when mating is:","0.002 in.",["0.000 in.","0.020 in.","0.200 in."],"1.000 − 0.998.")
H("824.d.5.B",4,"A shaft has limits 0.998 to 0.996 in. and a hole has limits 1.002 to 1.000 in. The maximum possible clearance is:","0.006 in.",["0.002 in.","0.004 in.","0.008 in."],"1.002 − 0.996.")
H("824.d.6.A",3,"A drafting department has a standard block that lists revision letters, dates and who approved each change. This standard practice is a:","revision history in the title area",["blueprint paper","lettering style","scale bar"],"Revision tables track changes.")
H("824.d.6.A",4,"The purpose of a revision history on a print is to:","track what changed, when and why",["hide changes","count parts","list tool names"],"Revisions document changes.")
H("824.d.6.B",3,"An engineer needs to change a hole size on a print. To keep it accurate, she should update the drawing and:","update the revision block and notify affected users",["leave the old copy in use","erase the note","hide the change"],"Control changes.")
H("824.d.6.B",4,"If a drawing is revised but the old print stays on the shop floor, the shop may:","build the part to the wrong size",["build it correctly","save time safely","avoid scrap"],"Obsolete prints cause errors.")
H("824.d.6.C",3,"A revision entry should include the date, a description of the change and:","the approval or initials of the person who made it",["the weather","the lunch menu","the machine color"],"Revision entries are signed.")
H("824.d.6.C",4,"Which is a correctly written revision entry?","Rev B – 03/12/2026 – Hole increased from 0.250 to 0.281 – J. Lee",["Rev B changed","Fixed","Updated stuff"],"Entries are specific.")

# ---- 828 Industrial Maintenance ----
H("828.d.1.A",3,"Rafael walks past a conveyor and hears a rhythmic squeal, feels extra vibration in the frame and sees a trace of oil under the motor. He is identifying a malfunction using:","visual, audible and other sensory inspection",["a lab test only","guessing from the price","a computer printout only"],"Eyes, ears and touch catch early problems.")
H("828.d.1.A",4,"A technician smells hot insulation near a motor starter panel. The best first response is to:","stop the equipment safely and report the odor",["keep the machine running","ignore it until the shift ends","spray water on the panel"],"Burning odors indicate overheating.")
H("828.d.1.B",3,"A press is moved by an oil pump, a cylinder and a control valve. This machine is mainly a:","hydraulic system",["pneumatic system","electrical system only","hand-powered system"],"Oil under pressure is hydraulic.")
H("828.d.1.B",4,"Compared with a hydraulic system, a pneumatic system uses:","compressed air as its working fluid",["oil as its working fluid","water only","gears only"],"Pneumatic = air.")
H("828.d.1.C",3,"Before servicing a belt-driven fan, Mia notes that the rotating shaft and pulley can catch loose sleeves and hair. This is a safety concern from:","rotating equipment",["static charge only","noise only","paint fumes only"],"Rotating parts can entangle.")
H("828.d.1.C",4,"Which practice reduces the danger of rotating equipment during maintenance?","lock out the machine and secure loose clothing and hair",["wear loose jewelry","work while it spins","remove the guards and run it"],"Control energy and avoid entanglement.")
H("828.d.1.D",3,"A training instructor writes steps for students to service a drill press: lock out power, gather tools, wear eye protection and verify zero energy. This is a:","safe plan of action for an industrial training setting",["random list","price list","sales plan"],"A safe plan lists steps in order.")
H("828.d.1.D",4,"A safe plan for a new maintenance training lab should be:","written, reviewed and followed by every student",["unwritten","skipped when busy","optional for visitors"],"Plans only work when followed.")
H("828.d.1.E",3,"To remove old paint and rust from a metal bracket before repair, a technician would choose a:","wire brush or abrasive pad",["paint roller","level","ruler"],"Cleaning uses abrasives and brushes.")
H("828.d.1.E",4,"Which tool would a technician use to cut a short section of steel pipe in the shop?","a pipe cutter or hacksaw",["a screw gun","a tape measure only","a spirit level"],"Cutting tools suit the task.")
H("828.d.1.F",3,"When using an abrasive cut-off saw, the operator should always:","wear eye and face protection and keep guards in place",["remove the guard","hold the work by hand without clamping","wear loose gloves near the blade"],"Guards and PPE protect.")
H("828.d.1.F",4,"A drill bit grabs and spins the workpiece. The most likely cause is that the part was:","not clamped securely",["too clean","painted","too short"],"Clamp the work.")
H("828.d.1.G",3,"To check a shaft diameter to 0.001 in., the technician selects a:","micrometer",["wood ruler","tape measure","yardstick"],"Micrometers read thousandths.")
H("828.d.1.G",4,"A dial caliper is able to measure all of the following EXCEPT:","internal volume of a tank",["inside diameter","outside diameter","depth"],"Calipers measure length features.")
H("828.d.1.H",3,"A technician replaces a bolt on a heavily loaded press with one of a lower grade. The risk is that the fastener may:","fail under load",["last longer","tighten itself","change color"],"Strength grade matters.")
H("828.d.1.H",4,"Hardened steel fasteners are chosen over soft aluminum ones when the joint must carry:","high loads",["no load","only a label","only decoration"],"Material strength matches the load.")
H("828.d.2.A",3,"A technician writes a one-page maintenance plan listing the equipment, the task, the interval and the parts needed. This is an example of:","technical communication",["a bank statement","a menu","a travel plan"],"Plans communicate work to others.")
H("828.d.2.A",4,"When explaining a machine problem to a supervisor, the technician should:","use specific observations and measurements",["use vague words","exaggerate","avoid details"],"Be precise.")
H("828.d.2.B",3,"Each time the oil on a gearbox is changed, a technician initials a sheet that stays with the machine. The sheet is a:","maintenance logbook entry",["menu","calendar of holidays","pay stub"],"Logbooks record work done.")
H("828.d.2.B",4,"A checklist for a daily equipment inspection helps a technician to:","make sure no inspection items are missed",["avoid inspections","guess results","skip documentation"],"Checklists improve consistency.")
H("828.d.2.C",3,"A technician schedules a monthly plan to grease the bearings on three motors, with the grease type, amount and who will do it. This is:","developing and executing a plan for a maintenance task",["buying lunch","painting walls","closing the shop"],"Plan the task, then do it.")
H("828.d.2.C",4,"When lubricating a bearing, over-greasing can:","overheat the bearing or blow the seals",["lower friction forever","never matter","remove the need for checks"],"Too much grease is harmful.")
H("828.d.3.A",3,"A shop supervisor leads a repair project by defining the goal, planning the steps, doing the work, checking progress and closing it out. These stages are:","initiating, planning, executing, monitoring and closing",["buying, selling, trading","painting, drying, packing","starting, quitting, resting"],"Project phases.")
H("828.d.3.A",4,"The stage of a project in which the team confirms the repair meets the requirements and finishes the paperwork is:","closing",["initiating","planning only","guessing"],"Closing wraps up.")
H("828.d.3.B",3,"To repair a damaged bracket, a technician drills out a broken screw, taps new threads and installs a larger screw. These are:","maintenance repair processes using appropriate tools",["painting steps","packing steps","selling steps"],"Repair uses tools and processes.")
H("828.d.3.B",4,"Before drilling a hole in a part, the technician should:","mark the center with a punch so the bit does not wander",["skip layout","hold the part in a hand","use a dull bit"],"Center punch guides the bit.")
H("828.d.3.C",3,"A hex nut on a pipe flange is tight in a cramped spot. For the best grip on all six sides of the nut, the technician should use a:","box end wrench",["pair of pliers","hammer","open end wrench only"],"Box wrenches grip all sides.")
H("828.d.3.C",4,"A technician needs to remove an oil filter that has no flat surfaces to grip. The tool for the job is a:","filter wrench",["torque wrench","hex key","feeler gauge"],"Filter wrenches grip round cases.")
H("828.d.4.A",3,"Under the Occupational Safety and Health Act, an employer must provide a workplace free of recognized hazards and a worker must:","follow safety rules and use required PPE",["ignore safety rules","remove guards","skip training"],"Both parties have duties.")
H("828.d.4.A",4,"Which is a responsibility of the employer for workplace safety?","provide training and required protective equipment",["avoid training","remove warning signs","charge for PPE in all cases"],"Employers must provide safe conditions.")
H("828.d.4.B",3,"OSHA standards matter in a shop because they:","set minimum requirements to protect workers from hazards",["decide the price of products","set the pay rates","approve company logos"],"OSHA sets safety standards.")
H("828.d.4.B",4,"A worker who reports a hazard to OSHA is protected from:","retaliation by the employer",["all inspections","paying taxes","all training"],"Workers have rights.")
H("828.d.4.C",3,"An OSHA compliance officer arrives at a plant, shows credentials, holds an opening conference, walks through the workplace and holds a closing conference. This describes how:","an OSHA inspection is conducted",["a fire drill is run","a sales call is made","an audit of payroll is run"],"Inspections follow a process.")
H("828.d.4.C",4,"After an OSHA inspection finds violations, the employer typically receives:","a citation and a deadline to correct the hazards",["a gift","no notice","a trophy"],"Citations specify abatement dates.")
H("828.d.4.D",3,"A state agency and a national agency both work to enforce workplace safety rules. The national agency that sets most workplace safety standards is:","OSHA",["the post office","the FAA","the IRS"],"OSHA is the federal safety agency.")
H("828.d.4.D",4,"NIOSH's role in workplace safety is mainly to:","research hazards and recommend ways to prevent injuries",["issue citations","set pay rates","collect taxes"],"NIOSH conducts research.")
H("828.d.4.E",3,"Excessive noise, dust that irritates the lungs, mold and repetitive lifting are all examples of:","industrial hygiene hazards",["marketing hazards","payroll hazards","parking hazards"],"Physical, chemical, biological and ergonomic.")
H("828.d.4.E",4,"Lifting heavy parts repeatedly with poor posture is mainly an:","ergonomic hazard",["chemical hazard","biological hazard","radiation hazard"],"Ergonomics concerns body strain.")
H("828.d.4.F",3,"A maintenance team wipes up an oil spill, covers cords in a walkway and puts railings on a platform. These actions support:","safe walking and working surfaces",["paint selection","machine speed","tool sales"],"Surface safety prevents falls.")
H("828.d.4.F",4,"The most common cause of injuries on walking surfaces is:","slips, trips and falls",["laser exposure","noise","radiation"],"Slips, trips and falls.")
H("828.d.4.G",3,"Exposed wiring, overloaded outlets and damaged cords are examples of:","electrical hazards in the workplace",["ergonomic hazards","biological hazards","noise hazards"],"Electrical hazards cause shock and fire.")
H("828.d.4.G",4,"A worker touching a live conductor can receive:","an electric shock or burn",["a free meal","only a sound","no effect"],"Contact causes shock.")
H("828.d.4.H",3,"Plugging power tools into a ground-fault circuit interrupter outlet and replacing frayed cords are:","control methods to prevent electrical hazards",["decorating ideas","advertising tips","scheduling aids"],"GFCIs and repairs prevent shock.")
H("828.d.4.H",4,"A key control method for electrical hazards is:","lockout/tagout before servicing equipment",["working on live panels","removing grounds","ignoring labels"],"De-energize first.")
H("828.d.4.I",3,"A worker stores solvent cans near an ignition source and transports them without secure lids. This shows a hazard in:","handling and storing hazardous materials",["painting","marketing","scheduling"],"Improper handling is dangerous.")
H("828.d.4.I",4,"Hazardous materials should be transported in:","approved, closed and labeled containers",["open buckets","unlabeled bottles","pockets"],"Containers must be approved.")
H("828.d.4.J",3,"A shop installs local exhaust ventilation at the solvent tank and requires gloves and goggles when handling it. These steps:","reduce exposure to hazardous materials",["increase exposure","remove the tank","ignore the hazard"],"Engineering and PPE reduce exposure.")
H("828.d.4.J",4,"Substituting a less hazardous cleaning product for a more toxic one is a way to:","reduce exposure at the source",["increase risk","avoid training","hide hazards"],"Substitution reduces hazard.")
H("828.d.4.K",3,"A new technician looks at the posted emergency plan, the eyewash station map and the safety data sheet binder. These are:","workplace health and safety resources",["decorations","sales tools","pay resources"],"Know where resources are.")
H("828.d.4.K",4,"Where can a technician find information about the hazards of a specific chemical?","the safety data sheet",["the break room menu","the time clock","the shipping schedule"],"SDS covers hazards.")
H("828.d.4.L",3,"A company has a written safety and health program with management commitment, worker participation and hazard identification. These are:","elements of a safety and health program",["parts of a sales plan","pieces of a menu","tools of marketing"],"Program elements.")
H("828.d.4.L",4,"A safety and health program works best when management:","shows leadership and involves workers",["avoids safety talks","blames workers","ignores reports"],"Leadership is key.")
H("828.d.4.M",3,"A plant keeps a written plan that explains what workers should do if a fire breaks out, how to report it and who is in charge. This is an:","emergency action and fire protection plan",["inventory sheet","menu plan","pay chart"],"Written plans guide emergencies.")
H("828.d.4.M",4,"A written emergency action plan must include:","how to report emergencies and how to evacuate",["the price of equipment","a holiday schedule","a staff party menu"],"Plans include reporting and evacuation.")
H("828.d.4.N",3,"A building posts a map showing marked exits, a meeting place outside and the location of extinguishers. These are:","key components of an evacuation plan",["pieces of a sales brochure","parts of a pay chart","elements of a menu"],"Routes and assembly points.")
H("828.d.4.N",4,"An emergency exit route must be:","kept clear and unlocked during working hours",["blocked with boxes","locked at all times","hidden"],"Exits stay clear.")
H("828.d.4.O",3,"A plant has trained workers who serve as first responders, fire wardens and the person who calls emergency services. These are:","emergency personnel within an organization",["marketing staff","payroll staff","visitors"],"Roles in emergencies.")
H("828.d.4.O",4,"A fire warden's job during an evacuation is to:","help ensure everyone leaves and is accounted for",["start the machines","lock the exits","collect pay"],"Wardens help with evacuation.")
H("828.d.4.P",3,"A shop labels chemical containers, keeps safety data sheets handy and trains workers on chemical hazards. These are parts of a:","hazard communication program",["pricing program","travel program","sales program"],"HazCom includes labels, SDS and training.")
H("828.d.4.P",4,"Under the hazard communication standard, a container of a hazardous chemical must have a:","label identifying the product and its hazards",["blank cover","price tag only","company song"],"Labels communicate hazards.")
H("828.d.4.Q",3,"OSHA requires that employees get training on hazards they may face, such as lockout/tagout and hazard communication. This is an example of:","safety and health training requirements",["pay requirements","vacation policies","parking rules"],"OSHA specifies training.")
H("828.d.4.Q",4,"Training on a new chemical should happen:","before workers are exposed to it",["after an injury","never","after retirement"],"Train before exposure.")
H("828.d.5.A",3,"Used oil, spent solvent and oily rags are sorted into labeled containers and stored in a closed cabinet until a licensed hauler picks them up. This is:","proper storage and disposal of hazardous materials",["careless disposal","burning waste","dumping waste"],"Store labeled, dispose properly.")
H("828.d.5.A",4,"A technician has a half-full can of gasoline left from cleaning parts. Where should it be kept until it is properly disposed of?","in a closed, approved flammable-liquid cabinet",["on an open shelf by the grinder","in a plastic grocery bag","in the break room"],"Flammable storage rules.")
H("828.d.5.B",3,"For a maintenance task involving chemical splashes and flying chips, a technician puts on gloves, goggles and a face shield. These are:","personal protective equipment",["tool storage","office supplies","machine parts"],"PPE protects workers.")
H("828.d.5.B",4,"PPE should be selected based on:","the hazards of the task",["the color options","the cost alone","the coworker's taste"],"Hazard assessment.")
H("828.d.5.C",3,"Before changing a belt on a conveyor, Dana turns off the main disconnect, puts on her lock and tag and tries the start button to verify the machine will not run. She is performing:","lockout/tagout",["a break","a lube job","a cleaning only"],"Lockout/tagout controls energy.")
H("828.d.5.C",4,"Who may remove a lockout lock after servicing is complete?","the person who applied it",["any worker","the supervisor only without checking","the next shift automatically"],"Each worker uses their own lock.")
H("828.d.5.D",3,"Before using a portable circular saw, a technician checks the guard, sets the depth and clamps the work. This is:","safe operation of a power tool",["a break","a repair","a cleanup"],"Safe power tool use.")
H("828.d.5.D",4,"A drill press operator should never:","hold small parts by hand while drilling",["clamp the work","wear eye protection","secure loose hair"],"Hand-holding small parts is unsafe.")
H("828.d.5.E",3,"For grinding a metal weld, the technician chooses safety glasses, a face shield, hearing protection and gloves. This is selecting:","appropriate PPE for operating a power tool",["office clothing","sports gear","party wear"],"Power tool PPE.")
H("828.d.5.E",4,"For an angle grinder, the best combination of PPE includes:","a face shield over safety glasses and hearing protection",["sunglasses only","no PPE","a hat only"],"Flying debris and noise.")
H("828.d.6.A",3,"Every month a technician greases the bearings on a fan, cleans a filter and inspects belts before anything breaks. This is:","preventative maintenance",["breakdown repair","a sales call","a demolition"],"PM keeps equipment running.")
H("828.d.6.A",4,"The main goal of preventative maintenance is to:","prevent failures before they happen",["wait for failures","remove all inspections","increase downtime"],"Prevent failures.")
H("828.d.6.B",3,"A maintenance team reviews records showing a pump seal fails about every 90 days and decides to replace it every 75 days. They are setting a PM schedule based on:","data from machine breakdowns",["guesswork","calendar holidays","the weather"],"Use data to schedule PM.")
H("828.d.6.B",4,"If a bearing fails every 6 months on average, a reasonable PM interval to replace it would be:","about every 5 months",["every 12 months","every 3 years","never"],"Replace before failure.")
H("828.d.6.C",3,"Fixing a motor after it burns out is:","reactive maintenance",["preventative maintenance","predictive maintenance","project management"],"Reactive = after failure.")
H("828.d.6.C",4,"Using vibration readings to decide when a bearing will fail and replacing it just before is:","predictive maintenance",["reactive maintenance","preventative only","ordinary cleaning"],"Predictive uses condition data.")
H("828.d.7.A",3,"A student learns that students can become maintenance technicians, machinists, welders or CNC operators. These are:","special skill career pathways in manufacturing",["restaurant jobs","retail jobs","teaching jobs only"],"Career pathways.")
H("828.d.7.A",4,"A career pathway that focuses on keeping machines running in a factory is:","maintenance technician",["sales clerk","museum guide","cook"],"Maintenance techs keep equipment running.")
H("828.d.7.B",3,"A student joins a regional manufacturers' association and attends a career fair to meet professionals and learn about job openings. This shows the value of:","industry networking opportunities",["staying isolated","avoiding contacts","only studying alone"],"Networking opens doors.")
H("828.d.7.B",4,"Joining a professional organization like the Society of Manufacturing Engineers can help a worker:","meet professionals and learn about opportunities",["avoid learning","lose contacts","reduce skills"],"Organizations connect people.")
H("828.d.7.C",3,"In a plant, one person designs a new part, another sets up and programs the equipment, and another operates and maintains the machine. These are the roles of:","engineers, technologists and technicians",["only salespeople","only managers","only customers"],"Different roles in manufacturing.")
H("828.d.7.C",4,"Which role typically involves designing products and processes using advanced math and science?","engineer",["cashier","painter only","driver"],"Engineers design.")

B.balance()
